      'card.factorTree.title': 'Reizinātāju koks',
      'card.factorTree.desc': 'Dod jebkuram skaitlim reizinātāju koku un skaties, kā tas zaro zaru pēc zara līdz pirmskaitļu lapām.',
      'card.venn.title': 'Venna diagramma',
